import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
await pg.goto('http://127.0.0.1:8099/#/pages/inspection/index?kind=mid',{waitUntil:'domcontentloaded',timeout:25000}).catch(e=>console.log('goto',e.message))
await pg.waitForTimeout(2500)
const info=await pg.evaluate(()=>{
  const btn=document.querySelector('.counter-btn') // first = a minus btn
  return {
    firstDisabled: btn? btn.disabled:null,
    firstCls: btn?btn.className:null,
    opacity: btn?getComputedStyle(btn).opacity:null,
    allMinus: [...document.querySelectorAll('.counter-btn')].filter(b=>b.textContent.trim()==='−').map(b=>({disabled:b.disabled, op:getComputedStyle(b).opacity}))
  }
})
console.log(JSON.stringify(info,null,2))
// verify clicking a disabled minus at 0 doesn't change value: find a counter that shows 0
const before = await pg.evaluate(()=>{const c=document.querySelector('.counter'); return c?{val:c.querySelector('.counter-val').textContent}:null})
await pg.evaluate(()=>{const btns=[...document.querySelectorAll('.counter-btn')].filter(b=>b.textContent.trim()==='−'); const dis=btns.find(b=>b.disabled); if(dis) dis.click()})
await pg.waitForTimeout(300)
const after = await pg.evaluate(()=>{const c=document.querySelector('.counter'); return c?{val:c.querySelector('.counter-val').textContent}:null})
console.log('click disabled minus: before',JSON.stringify(before),'after',JSON.stringify(after))
await pg.evaluate(()=>{const els=[...document.querySelectorAll('.section-title')]; const t=els.find(e=>/绿化树木/.test(e.textContent)); if(t) t.scrollIntoView({block:'start'})})
await pg.waitForTimeout(300)
await pg.screenshot({path:'D:/repository/_md.png'})
await b.close()

